  ok(h && h.allGreen, 'every consumer renders an <img> from the data URI (Option-A ready): ' + (h ? h.passed + '/' + h.total : 'n/a'));
  const heroImg = d.querySelector('.c-chat-info__hero .c-avatar__img');
